import { VoxelLogicType } from "../VoxelLogicType";
export class VoxelLogicStateType extends VoxelLogicType {
    keys;
    init() {
        this.keys = Object.keys(this.data.value);
    }
    run(voxel) {
        this.voxelLogic.schema.startEncoding(voxel.getState());
        for (let i = 0; i < this.keys.length; i++) {
            const key = this.keys[i];
            if (this.data.value[key] !== this.voxelLogic.schema.get(key)) {
                return false;
            }
        }
        return true;
    }
    *getEffects() {
        for (const effect of this.data.true)
            yield effect;
        for (const effect of this.data.false)
            yield effect;
    }
}
